#include <system_error>
#include <iostream>
#include <string>

int main() {
  std::error_code ec(std::errc::invalid_argument);
  std::error_condition ec_cond = ec;
  std::cerr << "Error code: " << ec << ", condition: " << ec_cond << std::endl;
  // Comparison examples
  if (ec == std::error_code(std::errc::invalid_argument))
      std::cout << "Error codes are equal" << std::endl; 
  if (ec == ec_cond) 
      std::cout << "Error code and condition are equal" << std::endl;
  return 0;
}
